+                final String baseKey = key.endsWith(":UPDATE")
+                        ? key.substring(0, key.length() - ":UPDATE".length())
+                        : key;
+
+                // Parse the 5-part key: {topicId}:{topicName}:{partition}:{endOffset}:{brokerLeaderEpoch}
+                String[] parts = baseKey.split(":", 5);
