+        props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");
+        props.put(ConsumerConfig.EXCLUDE_INTERNAL_TOPICS_CONFIG, "false");  // Allow consuming internal topics
+
